// Sliding-window rate limiter backed by workflow static data.
// Static data persists only for production (active) executions and resets on restart.
// Multi-worker deployments: replace this node with Redis INCR + EXPIRE.
const MIN = 60 * 1000;
const BUCKETS = {
  session: { limit: 20, windowMs: 10 * MIN },
  sheet: { limit: 60, windowMs: 10 * MIN },
  global: { limit: 300, windowMs: 60 * MIN },
};
const FAIL_WINDOW_MS = 15 * MIN;

const store = $getWorkflowStaticData('global');
store.rl = store.rl || {};
store.rl.session = store.rl.session || {};
store.rl.sheet = store.rl.sheet || {};
store.rl.global = store.rl.global || [];
store.rl.fails = store.rl.fails || {};

const now = Date.now();
const body = $input.first().json.body || {};
const sessionId = String(body.sessionId ?? '').trim() || 'anonymous';
const sheetId = String(body.sheetId ?? '').trim();

// Prune expired timestamps so static data cannot grow unbounded.
const prune = (list, windowMs) => (list || []).filter((t) => now - t < windowMs);
for (const kind of ['session', 'sheet']) {
  for (const key of Object.keys(store.rl[kind])) {
    store.rl[kind][key] = prune(store.rl[kind][key], BUCKETS[kind].windowMs);
    if (!store.rl[kind][key].length) delete store.rl[kind][key];
  }
}
store.rl.global = prune(store.rl.global, BUCKETS.global.windowMs);
for (const key of Object.keys(store.rl.fails)) {
  const f = store.rl.fails[key];
  f.times = prune(f.times, FAIL_WINDOW_MS);
  if (f.lockedUntil && f.lockedUntil <= now) f.lockedUntil = 0;
  if (!f.times.length && !f.lockedUntil) delete store.rl.fails[key];
}

// Failed-credential lockout. Keys are "sheetId|empCode"; one sheet is one employee,
// so any active lock on this sheet blocks it (the frontend may not know the code yet).
let lockedUntil = 0;
if (sheetId) {
  for (const [key, f] of Object.entries(store.rl.fails)) {
    if (key.startsWith(sheetId + '|') && f.lockedUntil > lockedUntil) lockedUntil = f.lockedUntil;
  }
}
if (lockedUntil > now) {
  return [{ json: { throttled: true, reason: 'locked', retryAfter: Math.ceil((lockedUntil - now) / 1000), sessionId, sheetId } }];
}

// Volume buckets.
const lists = [
  [store.rl.session[sessionId] || [], BUCKETS.session],
  [store.rl.global, BUCKETS.global],
];
if (sheetId) lists.push([store.rl.sheet[sheetId] || [], BUCKETS.sheet]);

let retryAfter = 0;
for (const [list, cfg] of lists) {
  if (list.length >= cfg.limit) {
    retryAfter = Math.max(retryAfter, Math.ceil((list[0] + cfg.windowMs - now) / 1000));
  }
}
if (retryAfter > 0) {
  return [{ json: { throttled: true, reason: 'volume', retryAfter, sessionId, sheetId } }];
}

(store.rl.session[sessionId] = store.rl.session[sessionId] || []).push(now);
store.rl.global.push(now);
if (sheetId) (store.rl.sheet[sheetId] = store.rl.sheet[sheetId] || []).push(now);

return [{ json: { throttled: false, reason: '', retryAfter: 0, sessionId, sheetId } }];

// Pulls emp_code / password out of free text BEFORE the agent runs, and replaces
// the password with "[provided]" so it never reaches Gemini or the chat memory.
// The real value is handed to the verify / log tools directly from this node.
// Also reports whether this chat session is already verified (set by Record Credential Outcome).
const AWAIT_PASSWORD_MS = 10 * 60 * 1000;

const store = $getWorkflowStaticData('global');
store.auth = store.auth || {};       // "sessionId:sheetId" -> { empCode, until }
store.awaitPw = store.awaitPw || {}; // "sessionId:sheetId" -> { at, empCode } when the agent asked for the password

const body = $('Receive Chat Message').first().json.body || {};
const key = (String(body.sessionId ?? '').trim() || 'anonymous') + ':' + String(body.sheetId ?? '').trim();
const now = Date.now();
for (const k of Object.keys(store.auth)) if (!(store.auth[k].until > now)) delete store.auth[k];
for (const k of Object.keys(store.awaitPw)) if (!(now - (store.awaitPw[k]?.at ?? 0) <= AWAIT_PASSWORD_MS)) delete store.awaitPw[k];
const pending = store.awaitPw[key];

const raw = String(body.message ?? '');
let empCode = '';
let password = '';
let message = raw;

const pw = /\b(password|passwd|pwd)\b\s*(?:is\s+)?[:=\-–—]*\s*(\S+)/i.exec(raw);
if (pw) {
  password = pw[2].replace(/[.,;]+$/, '');
  const start = pw.index;
  message = raw.slice(0, start) + pw[1] + ' - [provided]' + raw.slice(start + pw[0].length);
  const code = /\b(?:emp(?:loyee)?\s*(?:code|id|no\.?|number)?|code)\b\s*(?:is\s+)?[:=\-–—]*\s*([A-Za-z0-9-]*\d[A-Za-z0-9-]*)/i.exec(raw);
  if (code) empCode = code[1];
} else {
  // "500410 / 199", "500410 | 199", "500410, 199"
  const pair = /^\s*([A-Za-z]*-?\d{3,})\s*[\/|,]\s*(\S+)\s*$/.exec(raw);
  if (pair) {
    empCode = pair[1];
    password = pair[2];
    message = empCode + ' / [provided]';
  } else if (pending && /^\S+$/.test(raw.trim())) {
    // The agent's last reply asked for the password and this reply is one token: it is the password.
    password = raw.trim();
    message = '[password provided]';
  }
}
// awaitPw is cleared by Record Credential Outcome only after the agent answers, so a password
// resent after a failed run (e.g. a Gemini outage) is still recognised.

const auth = store.auth[key];
// A bare password is checked against the Employee Code the user sent just before being asked for it.
if (password && !empCode && pending) empCode = pending.empCode || '';

return [{ json: { message, empCode, password, credentialsProvided: password !== '', verifiedEmpCode: auth ? auth.empCode : '' } }];

// Rate limiter, response side: counts failed credential checks reported by
// workflow B (never the agent's own judgement) and locks the key after 5 in 15 min.
// Also keeps the per-session verification (30 min) and notes when the agent asked for the password.
const MAX_FAILS = 5;
const FAIL_WINDOW_MS = 15 * 60 * 1000;
const SESSION_MS = 30 * 60 * 1000;

const store = $getWorkflowStaticData('global');
store.rl = store.rl || {};
store.rl.fails = store.rl.fails || {};
store.auth = store.auth || {};
store.awaitPw = store.awaitPw || {};

const now = Date.now();
const req = $('Normalise Request').first().json;
const key = req.memoryKey;
const agent = $input.first().json;
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

// Tool observations arrive as JSON strings, sometimes wrapped in [{...}] or {response: ...}.
const unwrap = (value) => {
  let v = value;
  for (let i = 0; i < 6; i++) {
    if (typeof v === 'string') {
      try { v = JSON.parse(v); } catch { return null; }
    } else if (Array.isArray(v)) {
      v = v[0];
    } else if (v && typeof v === 'object' && !('ok' in v) && ('json' in v || 'response' in v)) {
      v = v.json ?? v.response;
    } else {
      break;
    }
  }
  return v && typeof v === 'object' && 'ok' in v ? v : null;
};

let log = null;
let lastReason = '';
const outcomes = [];
// Deterministic verification run before the agent (when a password was supplied this turn).
if ($('Verify Credentials').isExecuted) {
  const v = unwrap($('Verify Credentials').first().json);
  if (v) outcomes.push({ result: v, code: String(v.emp_code ?? $('Parse Credentials').first().json.empCode ?? '').trim() });
}
for (const step of steps) {
  if (step?.action?.tool !== 'log_timesheet_entry') continue;
  const result = unwrap(step.observation);
  if (!result) continue;
  log = result;
  outcomes.push({ result, code: String(step.action.toolInput?.emp_code ?? req.verifiedEmpCode ?? '').trim() });
}
for (const { result, code } of outcomes) {
  lastReason = result.reason || '';
  const failKey = req.sheetId + '|' + code;
  if (result.reason === 'invalid_credentials') {
    const f = (store.rl.fails[failKey] = store.rl.fails[failKey] || { times: [], lockedUntil: 0 });
    f.times = f.times.filter((t) => now - t < FAIL_WINDOW_MS);
    f.times.push(now);
    if (f.times.length >= MAX_FAILS) f.lockedUntil = now + FAIL_WINDOW_MS;
    delete store.auth[key];
  } else if (result.reason === 'credentials_required') {
    delete store.auth[key];
  } else if (result.ok === true) {
    delete store.rl.fails[failKey];
    const empCode = String(result.emp_code ?? store.auth[key]?.empCode ?? code);
    store.auth[key] = { empCode, until: now + SESSION_MS };
  }
}

const reply = String(agent.output ?? '').trim();
if (/enter your password/i.test(reply)) {
  // Remember the Employee Code from this turn's message; the next one-word reply is checked against it.
  const code = /[A-Za-z]*-?\d{3,}[A-Za-z0-9-]*/.exec(String(req.message ?? ''));
  store.awaitPw[key] = { at: now, empCode: code ? code[0] : (store.awaitPw[key]?.empCode ?? '') };
} else {
  delete store.awaitPw[key];
}

return [{ json: { sessionId: req.sessionId, sheetId: req.sheetId, reply, log, lastReason } }];
